import sys

def emit(text):
    sys.stdout.buffer.write(text.encode("utf-8"))

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    cap = int(data[pos]); pos += 1
    n = int(data[pos]); pos += 1
    refs = [int(tok) for tok in data[pos:pos + n]]
    order = []                      # least recently used -> most recently used
    for key in refs:
        if key in order:
            order.remove(key)
        elif len(order) >= cap:
            order.pop(0)
        order.append(key)
    emit(" ".join(str(k) for k in order) + "\n")

main()

