import sys

def emit(text):
    sys.stdout.buffer.write(text.encode("utf-8"))

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    total = int(data[pos]); pos += 1
    r = int(data[pos]); pos += 1
    sizes = [int(tok) for tok in data[pos:pos + r]]
    used = [False] * total
    out = []
    for need in sizes:
        start = -1
        for s in range(0, total - need + 1):
            if not any(used[s + i] for i in range(need)):
                start = s
                break
        if start < 0:
            out.append("-1")
        else:
            for i in range(start, start + need):
                used[i] = True
            out.append(" ".join(str(i) for i in range(start, start + need)))
    emit("\n".join(out) + "\n")

main()

import sys

def emit(text):
    sys.stdout.buffer.write(text.encode("utf-8"))

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    n = int(data[pos]); pos += 1
    segments = []
    for _ in range(n):
        start = int(data[pos]); size = int(data[pos + 1]); pos += 2
        segments.append([start, size])
    r = int(data[pos]); pos += 1
    sizes = [int(tok) for tok in data[pos:pos + r]]
    out = []
    for need in sizes:
        chosen = -1
        for i in range(len(segments)):
            if segments[i][1] >= need:
                if chosen < 0 or segments[i][1] < segments[chosen][1]:
                    chosen = i
                elif segments[i][1] == segments[chosen][1]:
                    if segments[i][0] < segments[chosen][0]:
                        chosen = i
        if chosen < 0:
            out.append("-1")
            continue
        out.append(str(segments[chosen][0]))
        segments[chosen][0] += need
        segments[chosen][1] -= need
        if segments[chosen][1] == 0:
            del segments[chosen]
    emit("\n".join(out) + "\n")

main()

