def main():
    text = sys.stdin.read()
    line = text.split("\n")[0]
    stack = []
    for part in line.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
        else:
            stack.append(part)
    emit("/" + "/".join(stack) + "\n")

