import sys

def emit(text):
    sys.stdout.buffer.write(text.encode("utf-8"))

def main():
    lines = [ln.strip() for ln in sys.stdin.read().split("\n")]
    lines = [ln for ln in lines if ln]
    if not lines:
        return
    pos = 0
    n = int(lines[pos]); pos += 1
    tree = set()
    for _ in range(n):
        tree.add(lines[pos]); pos += 1
    q = int(lines[pos]); pos += 1
    out = []
    for _ in range(q):
        fields = lines[pos].split(); pos += 1
        cwd = fields[0]
        target = fields[1]
        if target.startswith("/"):
            stack = []
            rest = target
        else:
            stack = [p for p in cwd.split("/") if p]
            rest = target
        for part in rest.split("/"):
            if part == "" or part == ".":
                continue
            if part == "..":
                if stack:
                    stack.pop()
            else:
                stack.append(part)
        resolved = "/" + "/".join(stack)
        out.append(resolved if resolved in tree else "NOT FOUND")
    emit("\n".join(out) + "\n")

main()

