def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    n = int(data[pos]); pos += 1
    intervals = []
    for _ in range(n):
        left = int(data[pos]); right = int(data[pos + 1]); pos += 2
        intervals.append((left, right))
    intervals.sort()
    merged = []
    for left, right in intervals:
        if merged and left <= merged[-1][1]:
            if right > merged[-1][1]:
                merged[-1][1] = right
        else:
            merged.append([left, right])
    out = ["%d %d" % (left, right) for left, right in merged]
    if out:
        emit("\n".join(out) + "\n")

